const items = $input.first().json.value;
const porMes = {};

for (const f of items) {
  const m = f.name.match(/Relatorio_Unificado (\d{4}-\d{2})\.xlsx$/i);
  if (!m) continue; // ignora qualquer arquivo fora do padrão de nome
  const mes = m[1];
  const atual = porMes[mes];
  if (!atual || new Date(f.lastModifiedDateTime) > new Date(atual.lastModifiedDateTime)) {
    porMes[mes] = f;
  }
}

return Object.values(porMes).map(f => ({ json: f }));

const html = $('Buscar Molde HTML').item.json.data; // ajuste "data" se o campo tiver outro nome
const dashboardData = $('Consolidar Dashboard').item.json; // troque pelo nome exato que você deu ao node 7
const jsonText = JSON.stringify(dashboardData);
const finalHtml = html.replace('{{DASHBOARD_DATA_JSON}}', jsonText);
return [{ json: { html: finalHtml } }];

/**
 * n8n Code Node — Consolidação dos dados financeiros para o Dashboard.
 *
 * Onde encaixar: logo após o node que lê todas as linhas da aba "NIBO"
 * do Excel (Microsoft Excel 365 → Search rows / Get rows). Este node
 * espera receber, em $input.all(), um item por linha da planilha, com
 * as colunas: Pagamento ou recebimento, Categoria, Valor pago, Valor recebido
 * (as demais colunas — Contato, Descrição, Centro de Custo, etc. — não
 * são usadas aqui, podem estar presentes sem problema).
 *
 * Saída: um único item, cujo campo `json` é exatamente o objeto que o
 * dashboard espera. No node seguinte (que troca o placeholder no molde
 * do HTML), use uma expressão tipo:
 *   {{ JSON.stringify($json) }}
 * para pegar o texto pronto a inserir no lugar de {{DASHBOARD_DATA_JSON}}.
 */

const DATE_COL = 'Pagamento ou recebimento';
const CAT_COL = 'Categoria';
const PAGO_COL = 'Valor pago';
const RECEBIDO_COL = 'Valor recebido';

/* Saldo de abertura manual, referente à posição em 31/12/2024 — os exports
   mensais só começam em janeiro/2025, então esse valor fixo substitui o
   que antes era um lançamento manual no Excel mestre. Não deve mudar de novo. */
const OPENING_BALANCE = 18631.43;

function parseDate(v) {
  if (v instanceof Date && !isNaN(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    const s = v.trim();
    // formato dd/mm/aaaa
    const parts = s.split('/');
    if (parts.length === 3 && parts[2].length === 4) {
      const d = parseInt(parts[0], 10), m = parseInt(parts[1], 10), y = parseInt(parts[2], 10);
      const dt = new Date(y, m - 1, d);
      if (!isNaN(dt)) return dt;
    }
    // formato ISO 8601 (ex: 2026-06-05T15:30:00Z)
    const iso = new Date(s);
    if (!isNaN(iso)) return iso;
  }
  return null;
}

function cleanCat(c) {
  if (!c) return '(Sem categoria)';
  return String(c).trim().replace(/\s+/g, ' ');
}

function parseNumber(v) {
  if (typeof v === 'number') return v;
  if (typeof v === 'string') {
    let s = v.trim();
    if (!s) return 0;
    if (s.indexOf(',') !== -1) {
      s = s.replace(/\./g, '').replace(',', '.');
    }
    const n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }
  return 0;
}

function round2(v) { return Math.round((Number(v) || 0) * 100) / 100; }
function pad2(n) { return (n < 10 ? '0' : '') + n; }
function ymd(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
function ym(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1); }
function fmtDate(d) { return pad2(d.getDate()) + '/' + pad2(d.getMonth() + 1) + '/' + d.getFullYear(); }

// ---- Lê os itens vindos do node anterior (uma linha da planilha por item) ----
const inputItems = $input.all();

const rows = [];
for (const item of inputItems) {
  const r = item.json;
  const dateVal = parseDate(r[DATE_COL]);
  if (!dateVal) continue; // em aberto (sem data de liquidação) — ignora
  rows.push({
    date: dateVal,
    credit: Math.abs(parseNumber(r[RECEBIDO_COL])),
    debit: -Math.abs(parseNumber(r[PAGO_COL])),
    cat: cleanCat(r[CAT_COL])
  });
}

if (rows.length === 0) {
  throw new Error('Nenhuma linha com "' + DATE_COL + '" válida encontrada.');
}

rows.sort((a, b) => a.date - b.date);

const years = Array.from(new Set(rows.map(r => r.date.getFullYear()))).sort();

// ---- Mensal ----
const monthly = {};
rows.forEach(r => {
  const k = ym(r.date);
  if (!monthly[k]) monthly[k] = { credit: 0, debit: 0 };
  monthly[k].credit += r.credit;
  monthly[k].debit += r.debit;
});
const allMonths = Object.keys(monthly).sort();
let cum = OPENING_BALANCE;
const monthEndCum = {};
allMonths.forEach(k => {
  const net = monthly[k].credit + monthly[k].debit;
  cum = round2(cum + net);
  monthly[k] = {
    credit: round2(monthly[k].credit),
    debit: round2(monthly[k].debit),
    net: round2(net),
    cum: cum
  };
  monthEndCum[k] = cum;
});
const monthStartCum = {};
let prevCum = OPENING_BALANCE;
allMonths.forEach(k => {
  monthStartCum[k] = round2(prevCum);
  prevCum = monthEndCum[k];
});

// ---- Diário ----
const daily = {};
rows.forEach(r => {
  const k = ymd(r.date);
  if (!daily[k]) daily[k] = { credit: 0, debit: 0 };
  daily[k].credit += r.credit;
  daily[k].debit += r.debit;
});
Object.keys(daily).forEach(k => {
  daily[k].credit = round2(daily[k].credit);
  daily[k].debit = round2(daily[k].debit);
  daily[k].net = round2(daily[k].credit + daily[k].debit);
});

// ---- Categoria por ano / mês / dia ----
function addToCat(bucket, key, cat, r) {
  if (!bucket[key]) bucket[key] = {};
  if (!bucket[key][cat]) bucket[key][cat] = { credit: 0, debit: 0 };
  bucket[key][cat].credit += r.credit;
  bucket[key][cat].debit += r.debit;
}
function roundCatBucket(bucket) {
  Object.keys(bucket).forEach(key => {
    Object.keys(bucket[key]).forEach(cat => {
      bucket[key][cat].credit = round2(bucket[key][cat].credit);
      bucket[key][cat].debit = round2(bucket[key][cat].debit);
    });
  });
}

const catYear = {}, catMonth = {}, catDay = {};
rows.forEach(r => {
  addToCat(catYear, String(r.date.getFullYear()), r.cat, r);
  addToCat(catMonth, ym(r.date), r.cat, r);
  addToCat(catDay, ymd(r.date), r.cat, r);
});
roundCatBucket(catYear);
roundCatBucket(catMonth);
roundCatBucket(catDay);

const dashboardData = {
  years: years,
  period: { min: fmtDate(rows[0].date), max: fmtDate(rows[rows.length - 1].date) },
  monthly: monthly,
  month_start_cum: monthStartCum,
  daily: daily,
  category_by_year: catYear,
  category_by_month: catMonth,
  category_by_day: catDay
};

return [{ json: dashboardData }];

const https = require('https');
const crypto = require('crypto');

function httpsRequest(options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks).toString() }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

const htmlBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const sha1 = crypto.createHash('sha1').update(htmlBuffer).digest('hex');

// Passo 1: cria o deploy informando o hash do arquivo
const createBody = JSON.stringify({ files: { '/index.html': sha1 } });
const createResp = await httpsRequest({
  hostname: 'api.netlify.com',
  path: `/api/v1/sites/${$env.NETLIFY_SITE_ID}/deploys`,
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${$env.NETLIFY_TOKEN}`,
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(createBody)
  }
}, createBody);

const deploy = JSON.parse(createResp.body);

// Passo 2: se a Netlify pedir o conteúdo (arquivo novo/alterado), envia os bytes brutos
let uploadResult = null;
if (deploy.required && deploy.required.includes(sha1)) {
  const uploadResp = await httpsRequest({
    hostname: 'api.netlify.com',
    path: `/api/v1/deploys/${deploy.id}/files/index.html`,
    method: 'PUT',
    headers: {
      'Authorization': `Bearer ${$env.NETLIFY_TOKEN}`,
      'Content-Type': 'application/octet-stream',
      'Content-Length': htmlBuffer.length
    }
  }, htmlBuffer);
  uploadResult = JSON.parse(uploadResp.body);
}

return [{ json: { deploy, uploadResult, sha1, tamanho: htmlBuffer.length } }];
